check('game starts, renders, and pauses correctly',()=>{g.start();assert.equal(g.inspect().wave,1);assert.ok(g.inspect().enemies.length>0);g.draw(1);g.pauseScreen();const old=g.inspect().p.cd.attack;g.attack();assert.equal(g.inspect().p.cd.attack,old);g.closeModal();});
check('mouse path cancelled by keyboard',()=>{for(const enemy of g.inspect().enemies)enemy.hp=0;elements.get('arena').listeners.pointerdown({button:0,clientX:100,clientY:600});assert.ok(g.inspect().path.length>0);win.listeners.keydown({key:'d',repeat:false});g.update(.016);assert.equal(g.inspect().path.length,0);assert.equal(g.inspect().target,null);win.listeners.keyup({key:'d'});});
check('skills enter targeting and an in-range confirmed dodge activates invulnerability',()=>{const {p,map}=g.inspect();Object.assign(p,{x:220,y:260,facing:0});g.skill('dash');assert.equal(g.inspect().pendingCast,'dash');g.skill('dash',{x:330,y:260},true);assert.equal(g.inspect().pendingCast,null);assert.ok(walkable(map,p.x,p.y,p.r));assert.ok(p.invuln>0);});
check('enemy killed once awards loot and experience once',()=>{g.start();const {p,enemies}=g.inspect(),e=enemies[0];g.harmEnemy(e,99999);const kills=p.kills,gold=p.gold;g.harmEnemy(e,99999);assert.equal(p.kills,kills);assert.equal(p.gold,gold);});
check('combat cannot open shop; cleared combat can',()=>{g.start();g.showShop();assert.notEqual(g.inspect().currentModal,'shop');for(const e of g.inspect().enemies)g.harmEnemy(e,99999);g.update(.01);assert.ok(g.inspect().cleared);g.closeModal();g.showShop();assert.equal(g.inspect().currentModal,'shop');assert.equal(g.inspect().stock.length,8);});
check('purchase, equip, sell and insufficient funds preserve inventory and gold',()=>{const s=g.inspect(),p=s.p;p.gold=1000;const item=s.stock[0],cost=g.price(item);click({buy:'0'});assert.equal(p.gold,1000-cost);assert.ok(p.inventory.includes(item));assert.equal(g.inspect().stock[0],null);const gold=p.gold;click({buy:'0'});assert.equal(p.gold,gold);g.equip(p.inventory.indexOf(item));if(item.slot==='weapon')assert.ok(p.weapons.includes(item));else assert.equal(p.equipment[item.slot],item);const saleItem=makeItem(1);p.inventory.push(saleItem);const index=p.inventory.indexOf(saleItem),sale=g.price(saleItem,true),before=p.gold;click({sell:String(index)});assert.equal(p.gold,before+sale);assert.ok(!p.inventory.includes(saleItem));p.gold=0;const len=p.inventory.length;click({buy:'1'});assert.equal(p.inventory.length,len);assert.equal(p.gold,0);});
check('refresh cost escalates and deep forging reaches +10 with expensive gains',()=>{const p=g.inspect().p;p.gold=10000;const gold=p.gold;click({action:'refresh'});assert.equal(p.gold,gold-15);click({action:'refresh'});assert.equal(p.gold,gold-40);const weapon={enhance:0};assert.deepEqual(Array.from({length:10},(_,level)=>{weapon.enhance=level;return g.forgeCost(weapon);}),[45,80,115,150,185,360,560,820,1160,1580]);assert.deepEqual(Array.from({length:10},(_,level)=>{weapon.enhance=level;return g.forgeGain(weapon);}),[5,5,5,5,5,10,13,16,19,22]);for(const marker of ["level>=10","深渊升华","Math.min(10,level+1)"])assert.ok(gameSource.includes(marker),marker);});
check('full backpack leaves loot on ground, picking twice cannot duplicate',()=>{const s=g.inspect(),p=s.p;p.inventory=Array.from({length:40},()=>makeItem());const drop={x:p.x,y:p.y,item:makeItem()};s.drops.push(drop);g.collect(drop);assert.ok(s.drops.includes(drop));p.inventory.pop();g.collect(drop);assert.equal(p.inventory.length,40);assert.ok(!s.drops.includes(drop));g.collect(drop);assert.equal(p.inventory.length,40);});
check('easy full run reaches victory through thirty encounters with boss CGs',()=>{g.selectDifficulty('easy');g.start();for(let encounter=0;encounter<30;encounter++){const s=g.inspect();assert.equal(s.floor,Math.floor(encounter/5)+1);assert.equal(s.wave,encounter%5+1);for(const e of s.enemies)g.harmEnemy(e,999999);g.update(.01);if(s.wave===5){assert.ok(g.inspect().cinematic);g.update(6);}if(encounter<29){while(g.inspect().currentModal==='talent')click({talent:'power'});g.closeModal();g.proceed();}}assert.ok(g.inspect().finished);assert.equal(g.inspect().currentModal,'result');assert.equal(g.inspect().floor,6);});
