check('bow and staff release projectiles on their impact frame while sword damage rises eighty percent',()=>{assert.equal(weaponInfo.sword.power,1.944);assert.ok(Math.abs(weaponInfo.sword.power/1.08-1.8)<1e-9);for(const kind of ['bow','staff']){click({weapon:kind});g.start();const scene=g.inspect();for(const row of scene.map)row.fill(0);scene.p.x=300;scene.p.y=300;for(const enemy of scene.enemies){enemy.x=850;enemy.y=300;enemy.hp=10000;}const before=g.inspect().shots.filter(shot=>shot.friendly).length;g.attack();assert.equal(g.inspect().shots.filter(shot=>shot.friendly).length,before,`${kind} must wait for the release frame`);g.update(.3);const friendly=g.inspect().shots.filter(shot=>shot.friendly);assert.equal(friendly.length,before+1,kind);assert.ok(friendly.at(-1).life<3.2&&friendly.at(-1).life>2.8);}assert.ok(gameSource.includes('ranged?visible'));});
check('basic attacks keep their target through the authored windup',()=>{click({weapon:'sword'});g.start();const state=g.inspect(),p=state.p,enemy=state.enemies[0];for(const row of state.map)row.fill(0);Object.assign(p,{x:300,y:300,facing:0});for(const other of state.enemies)other.hp=other===enemy?10000:0;Object.assign(enemy,{x:404,y:300,maxHp:10000,speed:0,cd:999,skill:999});const hp=enemy.hp;g.attack();assert.equal(p.attackTimeline.payload.targetId,enemy.id);Object.assign(enemy,{x:300,y:196});g.update(.22);assert.ok(enemy.hp<hp,'the sword should turn toward and hit the still-near locked target');});
check('locked bow and staff shots re-aim at release and softly track moving enemies',()=>{for(const kind of ['bow','staff']){click({weapon:kind});g.start();const state=g.inspect(),p=state.p,enemy=state.enemies[0];for(const row of state.map)row.fill(0);Object.assign(p,{x:300,y:300,facing:0});for(const other of state.enemies)other.hp=other===enemy?10000:0;Object.assign(enemy,{x:640,y:300,maxHp:10000,speed:0,cd:999,skill:999});g.attack();assert.equal(p.attackTimeline.payload.targetId,enemy.id);Object.assign(enemy,{x:300,y:100});g.update(.3);const shot=state.shots.find(projectile=>projectile.friendly);assert.ok(shot,kind);assert.equal(shot.targetId,enemy.id);assert.ok(shot.vy<0&&Math.abs(shot.vy)>Math.abs(shot.vx),`${kind} should release toward the target's current position`);}});
check('a quick attack press during the final cooldown window is buffered',()=>{click({weapon:'sword'});g.start();const state=g.inspect(),p=state.p,enemy=state.enemies[0];for(const row of state.map)row.fill(0);for(const other of state.enemies)other.hp=other===enemy?10000:0;Object.assign(enemy,{x:850,y:300,maxHp:10000,speed:0,cd:999,skill:999});Object.assign(p,{x:300,y:300,attackTimeline:null});p.cd.attack=.08;g.attack();assert.ok(p.attackBuffer>0);assert.equal(p.attackTimeline,null);g.update(.09);assert.ok(p.attackTimeline,'buffered attack should begin as soon as cooldown ends');assert.equal(p.attackBuffer,0);});
check('later enemy roster and room layouts are declared',()=>{for(const type of ['splitter','shaman','assassin','summoner'])assert.ok(gameSource.includes(`'${type}'`));for(const room of ['garden','forge','library','sanctum','observatory'])for(let floor=1;floor<=6;floor++){const map=createMap(floor,room),start=center(12,14);assert.ok(findPath(map,start,center(2,2)).length,`${room} floor ${floor} not reachable`);}});
check('mana skills and level growth work without automatic life leech',()=>{g.start();const s=g.inspect(),p=s.p;p.mana=80;g.skill('spin',{x:p.x,y:p.y-100},true);assert.ok(p.mana<80);assert.ok(p.cd.spin>0);const level=p.level,maxHp=p.maxHp,maxMana=p.maxMana,attack=playerStats(p).attack,leech=playerStats(p).leech;p.xp=p.xpGoal-1;g.addXP(1);assert.equal(p.level,level+1);assert.ok(p.maxHp>maxHp&&p.maxMana>maxMana&&playerStats(p).attack>attack);assert.equal(playerStats(p).leech,leech);const bossBefore=s.enemies.length;g.spawnEnemy('boss',center(12,3));const boss=g.inspect().enemies[bossBefore];g.harmEnemy(boss,999);assert.ok(boss.hp>0&&boss.lives===1&&boss.phase===2);g.harmEnemy(boss,99999);assert.equal(boss.hp,0);});
