check('difficulty keeps easy unchanged and sharply scales through inferno',()=>{g.selectDifficulty('easy');g.start();let before=g.inspect().enemies.length;g.spawnEnemy('crawler',center(12,3));const easy=g.inspect().enemies[before];g.selectDifficulty('normal');g.start();before=g.inspect().enemies.length;g.spawnEnemy('crawler',center(12,3));const normal=g.inspect().enemies[before];g.selectDifficulty('hard');g.start();before=g.inspect().enemies.length;g.spawnEnemy('crawler',center(12,3));const hard=g.inspect().enemies[before];g.selectDifficulty('hell');g.start();before=g.inspect().enemies.length;g.spawnEnemy('crawler',center(12,3));const hell=g.inspect().enemies[before];g.selectDifficulty('inferno');g.start();before=g.inspect().enemies.length;g.spawnEnemy('crawler',center(12,3));const inferno=g.inspect().enemies[before];assert.ok(normal.maxHp>=easy.maxHp*2.19&&normal.attack>=easy.attack*1.79);assert.ok(hard.maxHp>=easy.maxHp*4&&hard.attack>=easy.attack*3);assert.ok(hell.maxHp>=easy.maxHp*7&&hell.attack>=easy.attack*5);assert.ok(inferno.maxHp>=easy.maxHp*12&&inferno.attack>=easy.attack*8);g.selectDifficulty('easy');});
check('last three final-boss lives mirror all five difficulty multipliers',()=>{for(const [mode,mult] of [['easy',3],['normal',8],['hard',18],['hell',28],['inferno',45]]){g.selectDifficulty(mode);g.start();const before=g.inspect().enemies.length;g.spawnEnemy('boss',center(12,3));const boss=g.inspect().enemies[before],p=g.inspect().p,stats=playerStats(p);boss.phase=6;boss.lives=3;g.enterMirrorForm(boss);assert.ok(boss.mirror);assert.equal(boss.maxHp,p.maxHp*mult);assert.equal(boss.attack,Math.round(stats.attack*stats.weapon.power*mult));assert.equal(boss.form,`你的倒影 · ${stats.weapon.name}`);assert.ok(boss.speed>155*stats.weapon.speed);g.mirrorBasicAttack(boss);assert.ok(boss.cd<=stats.weapon.delay*.8+.001);}g.selectDifficulty('easy');for(const marker of ["const MIRROR_PHASE=6","['dash','spin','frost']",'drawAnimatedSprite(heroArt','if(isMirrorBoss(e)){mirrorCast(e)'])assert.ok(gameSource.includes(marker),marker);});
