check('targeted spells enforce MOBA-style maximum range and queue an approach order',()=>{click({weapon:'staff'});g.start();const state=g.inspect(),p=state.p;for(const row of state.map)row.fill(0);Object.assign(p,{x:120,y:360,mana:80});const farSide={x:900,y:360},mana=p.mana;g.skill('spin',farSide,true);assert.equal(p.mana,mana);assert.equal(p.cd.spin,0);assert.equal(g.inspect().queuedCast.name,'spin');assert.ok(g.inspect().path.length);for(let i=0;i<120&&!p.attackTimeline;i++)g.update(.05);assert.ok(p.mana<mana);assert.ok(p.cd.spin>0);assert.equal(g.inspect().queuedCast,null);assert.ok(p.attackTimeline);assert.equal(g.castRangeFor('spin','staff'),390);const preview=g.clampedCastPoint({x:p.x+900,y:p.y},390);assert.equal(preview.within,false);assert.ok(Math.abs(preview.x-p.x-390)<.001);});
check('staff shuttle leaves an exact ice trail, explodes at its endpoint, and keeps frost circular',()=>{
  click({weapon:'staff'});g.start();let state=g.inspect(),hero=state.p,point={x:500,y:320},inside=state.enemies[0],outside=state.enemies[1],blastIn=state.enemies[2],blastOut=state.enemies[3];
  for(const row of state.map)row.fill(0);Object.assign(hero,{x:260,y:320,mana:hero.maxMana,attackTimeline:null});for(const enemy of state.enemies)enemy.hp=[inside,outside,blastIn,blastOut].includes(enemy)?10000:0;
  Object.assign(inside,{x:410,y:320+36+inside.r-.5,maxHp:10000,speed:0,cd:999,skill:999});Object.assign(outside,{x:310,y:320+36+outside.r+.5,maxHp:10000,speed:0,cd:999,skill:999});
  Object.assign(blastIn,{x:point.x,y:point.y+78+blastIn.r-.5,maxHp:10000,speed:0,cd:999,skill:999});Object.assign(blastOut,{x:point.x,y:point.y-78-blastOut.r-.5,maxHp:10000,speed:0,cd:999,skill:999});
  let insideHp=inside.hp,outsideHp=outside.hp,blastInHp=blastIn.hp,blastOutHp=blastOut.hp;g.skill('spin',point,true);const cast=state.effects.find(effect=>effect.type==='heroSkillCast'&&effect.name==='spin');
  assert.ok(cast&&cast.areaShape==='capsule'&&cast.width===72&&cast.explosionRadius===78);assert.ok(Math.hypot(cast.ox-hero.x,cast.oy-hero.y)>20,'shuttle must originate at the staff muzzle');g.update(.56);
  assert.ok(inside.hp<insideHp,'spin must hit a body touching the 72-wide strip');assert.equal(outside.hp,outsideHp,'spin must not hit beyond the strip');assert.ok(blastIn.hp<blastInHp,'endpoint blast must hit a body touching radius 78');assert.equal(blastOut.hp,blastOutHp,'endpoint blast must not hit beyond radius 78');
  assert.ok(state.effects.some(effect=>effect.type==='heroSkillSignature'&&effect.name==='spin'&&effect.width===72&&effect.explosionRadius===78));const trail=state.hazards.find(hazard=>hazard.owner==='player'&&hazard.kind==='iceTrail');assert.ok(trail&&trail.width===72&&trail.max===2);assert.ok(Math.abs(trail.angle-Math.atan2(trail.endY-trail.startY,trail.endX-trail.startX))<1e-9,'trail must preserve the cast vector');insideHp=inside.hp;g.update(.25);assert.ok(inside.hp<insideHp,'ice trail must deal periodic damage');
  click({weapon:'staff'});g.start();state=g.inspect();hero=state.p;inside=state.enemies[0];outside=state.enemies[1];for(const row of state.map)row.fill(0);Object.assign(hero,{x:260,y:320,mana:hero.maxMana,attackTimeline:null});for(const enemy of state.enemies)enemy.hp=enemy===inside||enemy===outside?10000:0;
  Object.assign(inside,{x:point.x+165+inside.r-.5,y:point.y,maxHp:10000,speed:0,cd:999,skill:999});Object.assign(outside,{x:point.x+165+outside.r+.5,y:point.y,maxHp:10000,speed:0,cd:999,skill:999});insideHp=inside.hp;outsideHp=outside.hp;g.skill('frost',point,true);assert.ok(state.effects.some(effect=>effect.type==='heroSkillCast'&&effect.name==='frost'&&effect.areaShape==='circle'&&effect.radius===165));g.update(.7);assert.ok(inside.hp<insideHp,'frost must hit a body touching the 165-radius field');assert.equal(outside.hp,outsideHp,'frost must not hit beyond the field');assert.ok(state.effects.some(effect=>effect.type==='heroSkillSignature'&&effect.name==='frost'&&effect.radius===165));
  for(const marker of ['skillDamageAreas','skillDamageRadius','circleAreaHits','capsuleAreaHits','createPlayerIceTrail',"owner:'player'",'damageWidth=e.width||72','explosionRadius=e.explosionRadius||78','damageRadius=e.radius||165'])assert.ok(gameSource.includes(marker)||combatVfxSource.includes(marker),marker);
});
