check('player signatures and boss spells use separate layered WebGL choreography',()=>{click({weapon:'staff'});g.start();const state=g.inspect();state.p.invuln=9;state.effects.length=0;g.skill('spin',{x:420,y:320},true);assert.ok(state.effects.some(effect=>effect.type==='heroSkillCast'&&effect.kind==='staff'));g.update(.56);assert.ok(state.effects.some(effect=>effect.type==='heroSkillSignature'&&effect.name==='spin'));for(const marker of ['heroSkillSignature','heroSkillHit','bossImpactFlourish','bossVfxThemes','drawHeroSkillFootprint',"e.type==='heroSkillSignature'", "e.type==='vfxShard'"])assert.ok(gameSource.includes(marker),marker);});
check('WebGL2.5D pipeline provides masked materials, trails, lighting and restrained post-processing',()=>{for(const marker of ["getContext('webgl2'",'drawArraysInstanced','MAX_GPU_INSTANCES=420','u_scene','u_strength','SRC_ALPHA','ONE_MINUS_SRC_ALPHA','framebuffer','v_shape==8','v_shape==9','v_shape==15','fbm(vec2 p)'])assert.ok(webglSource.includes(marker),marker);for(const marker of ['createWebGLVfxRenderer','queueGpuProjectile','queueGpuEffect','queueGpuHazard','fxRenderer.flush()'])assert.ok(gameSource.includes(marker),marker);assert.ok(gameSource.includes("{color:'#82b96b'")&&gameSource.includes("style:'clock'")&&gameSource.includes("style:'crown'"));const fallback=webgl.namespace.createWebGLVfxRenderer(new Element());assert.equal(fallback.available,false);});
check('boss storms use a two-draw-call GPU compositor and bounded effect budgets',()=>{const state=g.inspect();state.effects.length=0;for(let i=0;i<500;i++)state.effects.push({type:'particle',life:1,max:1});for(let i=0;i<100;i++)state.effects.push({type:'energyRibbon',life:1,max:1});g.trimEffects();assert.ok(state.effects.length<=260);assert.ok(state.effects.filter(effect=>effect.type==='particle').length<=96);assert.ok(state.effects.filter(effect=>effect.type==='energyRibbon').length<=24);for(const marker of ['const fxCanvas=$(\'arena-fx\')','shots.slice(-48)','const MAX_EFFECTS=260','richBossImpacts<2'])assert.ok(gameSource.includes(marker),marker);assert.ok(!gameSource.includes('const FX_SCALE=.58'));});
check('high-rarity weapons keep their authored attack speed and critical hits do not freeze the simulation',()=>{g.start();const state=g.inspect(),weapon=state.p.equipment.weapon;weapon.rarity=5;g.attack();const premiumCooldown=state.p.cd.attack;state.p.cd.attack=0;state.p.attackTimeline=null;weapon.rarity=0;g.attack();assert.equal(state.p.cd.attack,premiumCooldown);const enemy=state.enemies.find(item=>item.hp>10),before=g.inspect().hitStop;g.harmEnemy(enemy,1,true);assert.equal(g.inspect().hitStop,before);assert.ok(!gameSource.includes('hitStop=Math.max(hitStop,critical'));});
check('all major equipment drops use three detailed bodies and six distinct silhouette kits',()=>{for(const kind of ['sword','bow','staff','armor','ring'])for(const tier of ['standard','epic','supreme']){const asset=`loot-${kind}-${tier}-v8.png`,path=new URL(`./${asset}`,import.meta.url);assert.ok(existsSync(path),asset);assert.ok(statSync(path).size>10000,asset);assert.ok(gameSource.includes(`'./${asset}'`),asset);}for(const marker of ['lootBodyTier','drawPremiumEquipmentDrop','drawLootQualityFrame','drawLootRarityHardware','bodyScale=[.9,.98,.93,1.03,.96,1.08]','lootEquipmentArts[key]','rarity===1','rarity===2','rarity===3','rarity===4','rarity>=5'])assert.ok(gameSource.includes(marker),marker);});
check('mid-run save restores the complete combat scene and exposes a continue card',()=>{click({weapon:'bow'});g.start();const before=g.inspect(),savedEnemy=before.enemies[0];before.p.gold=777;before.p.hp=888;before.p.inventory.push(makeItem(3,2,()=>.2));before.p.artifacts.push({...g.bossRewardInfo(4),used:false});savedEnemy.hp=Math.max(1,savedEnemy.hp-123);before.shots.push({x:211,y:322,vx:1,vy:2,life:2,damage:7,friendly:true});before.hazards.push({kind:'line',x:400,y:300,life:1,max:1});before.drops.push({id:88001,x:310,y:320,item:makeItem(2,1,()=>.3)});assert.equal(g.saveAndExit(),true);assert.ok(storage.has('abyss-run-v1'));assert.ok(elements.get('modal-content').innerHTML.includes('继续远征'));before.p.gold=0;savedEnemy.hp=1;assert.equal(g.resumeRun(),true);const restored=g.inspect();assert.equal(restored.p.gold,777);assert.equal(restored.p.hp,888);assert.equal(restored.p.equipment.weapon.kind,'bow');assert.equal(restored.p.inventory.length,1);assert.equal(restored.p.artifacts.length,1);assert.equal(restored.enemies[0].hp,JSON.parse(storage.get('abyss-run-v1')).enemies[0].hp);assert.equal(restored.shots.at(-1).damage,7);assert.equal(restored.hazards.at(-1).kind,'line');assert.equal(restored.drops.at(-1).id,88001);assert.equal(restored.effects.length,0);assert.equal(restored.running,true);assert.equal(restored.paused,false);});
check('settle and exit awards progress rewards once and removes the resumable run',()=>{g.selectDifficulty('easy');g.start();const state=g.inspect(),diamonds=state.profile.diamonds,runs=state.profile.totalRuns;state.p.kills=30;assert.equal(g.saveRunSnapshot(),true);assert.equal(g.settleAndExit(),true);assert.equal(g.inspect().currentModal,'result');assert.equal(g.inspect().profile.totalRuns,runs+1);assert.ok(g.inspect().profile.diamonds>diamonds);assert.equal(storage.has('abyss-run-v1'),false);assert.equal(g.settleAndExit(),false);});
check('walking cadence is distance-driven with natural held contact poses',()=>{assert.ok(ANIMATION_CLIPS.walk.duration>=1);assert.equal(walkFrameAt(.1),0);assert.equal(walkFrameAt(.3),1);assert.equal(walkFrameAt(.58),3);assert.ok(gameSource.includes('actualSpeed=moving?travel/Math.max(.001,dt):0'));assert.ok(gameSource.includes('weightShift=Math.sin(phase)*1.35'));assert.ok(!gameSource.includes('Math.min(dt*2,travel/90)'));});
check('idle rendering stays on one stable pose without additive transition flashes',()=>{for(const progress of [0,.2,.5,.9])assert.deepEqual({...motion.namespace.motionSample('idle',progress)},{first:0,next:0,blend:0});assert.ok(gameSource.includes("if(action==='idle')paint.drawImage(base,0,0)"));assert.ok(gameSource.includes("const moving=!!p.moving"));assert.ok(!gameSource.includes("paint.globalCompositeOperation='lighter';paint.globalAlpha=1-blend"));});
check('staff blink is instantaneous and creates no visual effects',()=>{click({weapon:'staff'});g.start();const state=g.inspect();state.effects.length=0;state.p.mana=state.p.maxMana;const before={x:state.p.x,y:state.p.y};g.skill('dash',{x:before.x+80,y:before.y},true);assert.ok(Math.hypot(before.x-state.p.x,before.y-state.p.y)>0);assert.equal(state.effects.length,0);assert.ok(state.p.silentBlinkInvuln>0);assert.ok(gameSource.includes("const silentBlink=kind==='staff'&&name==='dash'"));assert.ok(gameSource.includes("!(kind==='staff'&&name==='dash')"));assert.ok(gameSource.includes("p.invuln>0&&!(p.silentBlinkInvuln>0)?.78:1"));g.settleAndExit();});
check('slow status uses ice shell mist and ground cracks without a blue rectangle',()=>{for(const marker of ['drawFrozenStatus','drawFrostBurst','applySlow','frostBurst','霜缚'])assert.ok(gameSource.includes(marker)||vfxSource.includes(marker),marker);assert.ok(vfxSource.includes('createRadialGradient'));assert.ok(vfxSource.includes('softDisc'));assert.ok(!gameSource.includes("ctx.strokeRect(e.x-23,e.y-72,46,74)"));});
check('all six bosses have distinct signature VFX languages',()=>{for(const marker of ['Living stone','Forge fire','Astral court','Blood and bone','Time hunter','Final mirror'])assert.ok(vfxSource.includes(marker),marker);assert.ok(gameSource.includes("type:'bossSignature'"));assert.ok(gameSource.includes("floor,phase:'cast'"));assert.ok(gameSource.includes("floor,life:.62"));});
check('opening CG tells five story chapters before showing the main menu',()=>{assert.equal(opening.namespace.OPENING_STORY.length,5);for(const marker of ['太阳熄灭后的第七百年','王座破碎','守墓者吞下碎片','只有拾荒者','王座再次呼唤'])assert.ok(openingSource.includes(marker),marker);for(const marker of ['startOpeningCG','finishOpeningCG','drawOpeningStoryFrame','skip-opening','opening-progress'])assert.ok(gameSource.includes(marker)||openingSource.includes(marker),marker);assert.equal(g.inspect().openingCinematic,null);assert.equal(g.inspect().currentModal,'result');});
check('combat VFX system registers reusable timeline recipes for heroes and future bosses',()=>{const calls=[],renderer={};for(const method of ['trail','beam','disc','ring','light','shard','fissure','bladeArc','starCore','vortex','windWake','crescent','rock','royalArc','arrow','swordRibbon','bladeFlash'])renderer[method]=(...args)=>calls.push([method,...args]);const system=combatVfx.namespace.createCombatVfxSystem(renderer,{maxActive:2});assert.equal(system.inspect().length,15);for(const kind of ['sword','staff','bow'])for(const name of ['spin','frost'])assert.ok(system.hasCue(`hero.${kind}.${name}.impact`));for(const [kind,name] of [['sword','frost'],['staff','frost'],['bow','frost']])assert.equal(system.render({type:'heroSkillSignature',kind,name,x:500,y:350,ox:250,oy:350,angle:0,life:.5,max:1,color:'#88aaff',accent:'#ffffff',marks:[{x:470,y:330}]},1),true);for(const material of ['fissure','rock','vortex','starCore','crescent','windWake'])assert.ok(calls.some(call=>call[0]===material),material);system.render({type:'heroSkillSignature',kind:'sword',name:'spin',x:500,y:350,ox:250,oy:350,life:.5,max:1},1);system.render({type:'heroSkillSignature',kind:'bow',name:'spin',x:500,y:350,ox:250,oy:350,life:.5,max:1},1);for(const material of ['swordRibbon','bladeFlash','arrow'])assert.ok(calls.some(call=>call[0]===material),material);system.registerCue('boss.stone.test',c=>c.renderer.rock(c.event.x,c.event.y,20,0,c.color,1),{owner:'boss',duration:.5,priority:4});assert.equal(system.render({cue:'boss.stone.test',x:10,y:20,life:1,max:1},0),true);system.emit('boss.stone.test',{x:10,y:20});system.emit('hero.staff.frost.impact',{x:50,y:60,ox:30,oy:60});system.emit('hero.bow.spin.impact',{x:90,y:60,ox:30,oy:60,priority:0});assert.equal(system.activeCount(),2);system.renderActive(.1);system.update(2);assert.equal(system.activeCount(),0);assert.ok(system.inspect().some(cue=>cue.owner==='boss'));assert.ok(gameSource.includes('createCombatVfxSystem'));});
check('material-driven sword vertical slice loads atlases, flow, normals and distortion with quality tiers',()=>{const assets=['vfx-sword-slash-atlas-v8.png','vfx-sword-sparks-atlas-v8.png','vfx-sword-flow-v8.png','vfx-sword-normal-v8.png','vfx-sword-distortion-v8.png'];for(const asset of assets){const path=new URL(`./${asset}`,import.meta.url);assert.ok(existsSync(path),asset);assert.ok(statSync(path).size>100000,asset);}for(const marker of ['u_slashAtlas','u_flowMap','u_normalMap','u_distortionMap','u_sparkAtlas','assetSlash','assetSpark','assetsReady','v_shape==20','v_shape==21'])assert.ok(webglSource.includes(marker),marker);for(const marker of ['p.equipment.weapon.rarity','quality>=1','quality>=2','quality>=3'])assert.ok(gameSource.includes(marker)||combatVfxSource.includes(marker),marker);assert.ok(existsSync(new URL('./tools/build_vfx_maps.py',import.meta.url)));});
check('material-driven mage vertical slice owns its atlases, centered staged collapse, directed ice trail and endpoint burst',()=>{const assets=['vfx-staff-eclipse-atlas-v8.png','vfx-staff-collapse-atlas-v8.png','vfx-staff-flow-v8.png','vfx-staff-normal-v8.png','vfx-staff-distortion-v8.png','vfx-staff-ice-trail-v8.png','vfx-staff-ice-burst-v8.png'];for(const asset of assets){const path=new URL(`./${asset}`,import.meta.url);assert.ok(existsSync(path),asset);assert.ok(statSync(path).size>100000,asset);}for(const marker of ['u_eclipseAtlas','u_collapseAtlas','u_staffFlowMap','u_staffNormalMap','u_staffDistortionMap','u_staffTrailMap','u_staffBurstMap','assetEclipse','assetCollapse','assetEclipseEdge','assetEclipseVeil','assetCollapseEdge','assetCollapseMist','iceTrailSurface','iceBurst','v_shape==22','v_shape==23','v_shape==24','v_shape==25','v_shape==26','v_shape==27','v_shape==28','v_shape==29','edge*2.72','for(const [index,[name,uniform]]'])assert.ok(webglSource.includes(marker),marker);for(const marker of ['flipbook','assetEclipseEdge','assetEclipseVeil','assetCollapseEdge','assetCollapseMist','smooth(.25,.75,p)','beamLength,4.4+quality*.32','crystalReveal','perimeter','cx=e.x,cy=e.y','visualAngle=-angle','frozenLength','handoff','r.iceTrailSurface','r.iceBurst','quality>=1'])assert.ok(combatVfxSource.includes(marker),marker);for(const marker of ['visualAngle=-h.angle','staffShuttle?.72:staffCollapse?.82:.48','staffShuttle?8:staffCollapse?10:6','staffShuttle?6:staffCollapse?8:3'])assert.ok(gameSource.includes(marker),marker);assert.ok(!combatVfxSource.slice(combatVfxSource.indexOf('function staffSpin'),combatVfxSource.indexOf('function bowSpin')).includes('r.fissure'));assert.ok(gameSource.includes("name==='spin'?.72:.84"));assert.ok(gameSource.includes("if(!(kind==='staff'&&name==='frost'))skillImpactFlourish"));assert.ok(existsSync(new URL('./staff-vfx-material-qa.html',import.meta.url)));});
